33	using Workspace                = NVCVWorkspace;
34	using WorkspaceMem             = NVCVWorkspaceMem;
35	using WorkspaceRequirements    = NVCVWorkspaceRequirements;
36	using WorkspaceMemRequirements = NVCVWorkspaceMemRequirements;
37	
38	class WorkspaceError : public std::runtime_error
39	{
40	public:
41	    using std::runtime_error::runtime_error;
42	};
