44	/** Computes memory requirements that can cover both input requirements.
45	 *
46	 * The resulting memory requriements will have alignment and size that is not smaller than that of either
47	 * of the arguments.
48	 *
49	 * alignment = max(a.alignment, b.alignment)
50	 * size = align_up(max(a.size, b.size), alignment)
51	 */
52	inline WorkspaceMemRequirements MaxWorkspaceReq(WorkspaceMemRequirements a, WorkspaceMemRequirements b)
53	{
54	    WorkspaceMemRequirements ret;
55	    assert(!a.size || a.alignment > 0);
56	    assert(!b.size || b.alignment > 0);
57	    ret.alignment = b.alignment > a.alignment ? b.alignment : a.alignment;
58	    ret.size      = b.size > a.size ? b.size : a.size;
59	    assert((ret.alignment & (ret.alignment - 1)) == 0 && "Alignment must be a power of 2");
60	    ret.size = nvcv::detail::AlignUp(ret.size, ret.alignment);
61	    return ret;
62	}
63	
64	/** Computes workspace requirements that can cover both input requirments. */
65	inline NVCVWorkspaceRequirements MaxWorkspaceReq(const WorkspaceRequirements &a, const WorkspaceRequirements &b)
66	{
67	    WorkspaceRequirements ret;
68	    ret.hostMem   = MaxWorkspaceReq(a.hostMem, b.hostMem);
69	    ret.pinnedMem = MaxWorkspaceReq(a.pinnedMem, b.pinnedMem);
70	    ret.cudaMem   = MaxWorkspaceReq(a.cudaMem, b.cudaMem);
71	    return ret;
72	}
73	
74	inline void AlignUp(WorkspaceRequirements &ws)
75	{
76	    ws.hostMem.size   = nvcv::detail::AlignUp(ws.hostMem.size, ws.hostMem.alignment);
77	    ws.pinnedMem.size = nvcv::detail::AlignUp(ws.pinnedMem.size, ws.pinnedMem.alignment);
78	    ws.cudaMem.size   = nvcv::detail::AlignUp(ws.cudaMem.size, ws.cudaMem.alignment);
79	}
80	
81	inline void SynchronizeWorkspaceMem(const WorkspaceMem &mem)
82	{
83	    if (mem.ready && cudaEventSynchronize(mem.ready) != cudaSuccess)
84	    {
85	        throw WorkspaceError("cudaEventSynchronize failed");
86	    }
87	}
88	
89	template<class Allocator>
90	inline void FreeWorkspaceMem(WorkspaceMem &mem, Allocator alloc)
91	{
92	    if (!mem.data)
93	    {
94	        return;
95	    }
96	
97	    SynchronizeWorkspaceMem(mem);
98	    alloc.free(mem.data, static_cast<int64_t>(mem.req.size), static_cast<int32_t>(mem.req.alignment));
99	    mem.data = nullptr;
100	}
