102	/** A helper class that manages the lifetime of resources stored in a Workspace structure.
103	 *
104	 * This class works in a way similar to unique_ptr with a custom deleter.
105	 */
106	class UniqueWorkspace
107	{
108	public:
109	    using DeleterFunc = void(NVCVWorkspace &);
110	    using Deleter     = std::function<DeleterFunc>;
111	
112	    UniqueWorkspace() = default;
113	
114	    UniqueWorkspace(const UniqueWorkspace &) = delete;
115	
116	    UniqueWorkspace(UniqueWorkspace &&ws) noexcept
117	    {
118	        swap(ws);
119	    }
120	
121	    UniqueWorkspace &operator=(const UniqueWorkspace &) = delete;
122	
123	    UniqueWorkspace &operator=(UniqueWorkspace &&ws) noexcept
124	    {
125	        swap(ws);
126	        ws.resetNoThrow();
127	        return *this;
128	    }
129	
130	    explicit UniqueWorkspace(const Workspace &workspace, Deleter del = {})
131	        : m_impl(workspace)
132	        , m_del(std::move(del))
133	    {
134	    }
135	
136	    UniqueWorkspace(const WorkspaceMem &host, const WorkspaceMem &pinned, const WorkspaceMem &cuda, Deleter del = {})
137	        : m_impl{host, pinned, cuda}
138	        , m_del(std::move(del))
139	    {
140	    }
141	
142	    ~UniqueWorkspace() noexcept
143	    {
144	        resetNoThrow();
145	    }
146	
147	    void reset() noexcept
148	    {
149	        resetNoThrow();
150	    }
151	
152	    const Workspace &get() const
153	    {
154	        return m_impl;
155	    }
156	
157	private:
158	    void resetImpl()
159	    {
160	        if (m_del)
161	        {
162	            m_del(m_impl);
163	            m_del  = {};
164	            m_impl = {};
165	        }
166	    }
167	
168	    void resetNoThrow() noexcept
169	    {
170	        try
171	        {
172	            resetImpl();
173	        }
174	        catch (...)
175	        {
176	            m_del  = {};
177	            m_impl = {};
178	        }
179	    }
180	
181	    void swap(UniqueWorkspace &ws) noexcept
182	    {
183	        std::swap(m_impl, ws.m_impl);
184	        std::swap(m_del, ws.m_del);
185	    }
186	
187	    Workspace m_impl{};
188	    Deleter   m_del{};
189	};
