191	/** Allocates a workspace with an allocator specified in `alloc` (or a default one).
192	 *
193	 * This function is meant as a simple helper to simplify the usage operators requiring a workspace, but its intense use
194	 * may degrade performance due to excessive allocations and deallocations.
195	 * For code used in tight loops, some workspace reuse scheme and/or resource pools are recommended.
196	 */
197	inline UniqueWorkspace AllocateWorkspace(const WorkspaceRequirements &req, nvcv::Allocator alloc = {})
198	{
199	    if (!alloc)
200	    {
201	        nvcv::CustomAllocator<> cust{};
202	        alloc = std::move(cust);
203	    }
204	    auto del = [alloc](NVCVWorkspace &ws)
205	    {
206	        // REVISIT(michalz): Add proper CUDA error handling in public API
207	        FreeWorkspaceMem(ws.hostMem, alloc.hostMem());
208	        FreeWorkspaceMem(ws.pinnedMem, alloc.hostPinnedMem());
209	        FreeWorkspaceMem(ws.cudaMem, alloc.cudaMem());
210	    };
211	    NVCVWorkspace ws = {};
212	    try
213	    {
214	        ws.hostMem.req   = req.hostMem;
215	        ws.pinnedMem.req = req.pinnedMem;
216	        ws.cudaMem.req   = req.cudaMem;
217	
218	        if (req.hostMem.size)
219	            ws.hostMem.data = alloc.hostMem().alloc(static_cast<int64_t>(req.hostMem.size),
220	                                                    static_cast<int32_t>(req.hostMem.alignment));
221	        if (req.pinnedMem.size)
222	            ws.pinnedMem.data = alloc.hostPinnedMem().alloc(static_cast<int64_t>(req.pinnedMem.size),
223	                                                            static_cast<int32_t>(req.pinnedMem.alignment));
224	        if (req.cudaMem.size)
225	            ws.cudaMem.data = alloc.cudaMem().alloc(static_cast<int64_t>(req.cudaMem.size),
226	                                                    static_cast<int32_t>(req.cudaMem.alignment));
227	        return UniqueWorkspace(ws, std::move(del));
228	    }
229	    catch (...)
230	    {
231	        del(ws);
232	        throw;
233	    }
234	}
235	
236	} // namespace cvcuda
