31	template<MemoryKind kind>
32	void ReleaseWorkspaceMem(WorkspaceMemCache<kind> &cache, CachedWorkspaceMem<kind> &mem,
33	                         std::optional<cudaStream_t> releaseStream) noexcept
34	{
35	    if (!mem)
36	        return;
37	
38	    try
39	    {
40	        cache.put(std::move(mem), releaseStream);
41	    }
42	    catch (...)
43	    {
44	        mem.reset();
45	    }
46	}
