49	
50	WorkspaceLease::WorkspaceLease(WorkspaceCache *owner, CachedWorkspaceMem<MemoryKind::Host> &&host,
51	                               CachedWorkspaceMem<MemoryKind::Pinned> &&pinned,
52	                               CachedWorkspaceMem<MemoryKind::Cuda>   &&cuda,
53	                               std::optional<cudaStream_t>              hostReleaseStream,
54	                               std::optional<cudaStream_t>              pinnedReleaseStream,
55	                               std::optional<cudaStream_t>              cudaReleaseStream)
56	    : m_owner(owner)
57	    , m_host(std::move(host))
58	    , m_pinned(std::move(pinned))
59	    , m_cuda(std::move(cuda))
60	    , m_hostReleaseStream(std::move(hostReleaseStream))
61	    , m_pinnedReleaseStream(std::move(pinnedReleaseStream))
62	    , m_cudaReleaseStream(std::move(cudaReleaseStream))
63	{
64	}
65	
66	WorkspaceLease::~WorkspaceLease() noexcept
67	{
68	    if (m_owner == nullptr)
69	        return;
70	
71	    ReleaseWorkspaceMem(m_owner->m_host, m_host, m_hostReleaseStream);
72	    ReleaseWorkspaceMem(m_owner->m_pinned, m_pinned, m_pinnedReleaseStream);
73	    ReleaseWorkspaceMem(m_owner->m_cuda, m_cuda, m_cudaReleaseStream);
74	}
75	
76	WorkspaceCache::WorkspaceCache(nvcv::Allocator allocator)
77	    : m_eventCache(std::make_shared<nvcv::util::EventCache>())
78	    , m_host(allocator, m_eventCache)
79	    , m_pinned(allocator, m_eventCache)
80	    , m_cuda(allocator, m_eventCache)
81	{
82	}
83	
84	WorkspaceCache::WorkspaceCache()
85	    : WorkspaceCache(nvcv::CustomAllocator<>{})
86	{
87	}
88	
89	WorkspaceLease WorkspaceCache::get(const cvcuda::WorkspaceRequirements &req,
90	                                   std::optional<cudaStream_t>          hostAcquireStream,
91	                                   std::optional<cudaStream_t>          hostReleaseStream,
92	                                   std::optional<cudaStream_t>          pinnedAcquireStream,
93	                                   std::optional<cudaStream_t>          pinnedReleaseStream,
94	                                   std::optional<cudaStream_t>          cudaAcquireStream,
95	                                   std::optional<cudaStream_t>          cudaReleaseStream)
96	{
97	    return WorkspaceLease(this, m_host.get(req.hostMem, hostAcquireStream),
98	                          m_pinned.get(req.pinnedMem, pinnedAcquireStream), m_cuda.get(req.cudaMem, cudaAcquireStream),
99	                          hostReleaseStream, pinnedReleaseStream, cudaReleaseStream);
100	}
101	
102	WorkspaceCache &WorkspaceCache::instance()
103	{
104	    // Per-device singleton: each CUDA device gets its own WorkspaceCache
105	    // so that device memory allocations are always on the correct GPU.
106	    // Uses shared_ptr for heap stability — unordered_map rehashing won't
107	    // invalidate the objects that outstanding references point to.
108	    static std::unordered_map<int, std::shared_ptr<WorkspaceCache>> instances;
109	    static std::shared_mutex                                        instances_mutex;
110	
111	    int dev = 0;
112	    nvcvpy::util::CheckThrow(cudaGetDevice(&dev));
113	
114	    // Shared lock: concurrent readers when the entry already exists.
115	    {
116	        std::shared_lock lock(instances_mutex);
117	        auto             it = instances.find(dev);
118	        if (it != instances.end())
119	            return *it->second;
120	    }
121	
122	    // Exclusive lock: serializes the one-time insertion of a new entry.
123	    std::unique_lock lock(instances_mutex);
124	    auto [it, _] = instances.try_emplace(dev, nullptr);
125	    if (!it->second)
126	        it->second = std::make_shared<WorkspaceCache>();
127	    return *it->second;
128	}
129	
130	void WorkspaceCache::clear()
131	{
132	    m_cuda.clear();
133	    m_pinned.clear();
134	    m_host.clear();
135	    m_eventCache->purge();
136	}
