19	#define NVCV_UTIL_SIMPLE_CACHE_HPP
20	
21	#include <memory>
22	#include <mutex>
23	#include <optional>
24	
25	namespace nvcv::util {
26	
27	/** A simple cache that stores objects of type T
28	 *
29	 * The cache stores objects of type T. Upon a call to `Get`, an object
30	 * is moved out from the cache and returned as `optional<T>`. If the cache
31	 * is empty, `nullopt` is returned.
32	 * `GetOrCreate` alwas returns an object (unless it throws) - if the cache is empty,
33	 * a user-provided factory function is invoked and a new object is returned.
34	 * Objects can be placed in the cache with a call to `Put` or `Emplace`.
35	 *
36	 * The cache is guarded with a lockable object (by default std::mutex).
37	 *
38	 * The cache is implemented as a unidirectional list of entries.
39	 * Each entry holds an optional instance of type T.
40	 * Once an object is removed, the cache entry is stored for reuse in an auxiliary list,
41	 * reducing the number of dynamic allocations.
42	 *
43	 * @tparam T        The type of itmes held in the cache
44	 * @tparam LockType A lockable object
45	 */
46	template<typename T, typename LockType = std::mutex>
47	class SimpleCache
48	{
49	public:
50	    std::optional<T> get()
51	    {
52	        if (m_items)
53	        {
54	            std::lock_guard lg(m_lock);
55	            if (m_items)
56	            {
57	                auto tmp  = std::move(m_items);
58	                m_items   = std::move(tmp->next);
59	                auto obj  = std::move(tmp->payload);
60	                tmp->next = std::move(m_empty);
61	                m_empty   = std::move(tmp);
62	                return obj;
63	            }
64	        }
65	        return std::nullopt;
66	    }
67	
68	    template<typename CreateFunc>
69	    T getOrCreate(CreateFunc &&create)
70	    {
71	        auto cached = get();
72	        if (cached.has_value())
73	            return std::move(cached).value();
74	        else
75	            return create();
76	    }
77	
78	    void put(T &&payload)
79	    {
80	        emplace(std::move(payload));
81	    }
82	
83	    template<typename... Args>
84	    void emplace(Args &&...args)
85	    {
86	        std::lock_guard lg(m_lock);
87	
88	        std::unique_ptr<CacheItem> item;
89	        if (m_empty)
90	        {
91	            item    = std::move(m_empty);
92	            m_empty = std::move(item->next);
93	        }
94	        else
95	        {
96	            item = std::make_unique<CacheItem>();
97	        }
98	        item->payload.emplace(std::forward<Args>(args)...);
99	
100	        item->next = std::move(m_items);
101	        m_items    = std::move(item);
102	    }
103	
104	    void purge()
105	    {
106	        std::lock_guard lg(m_lock);
107	
108	        m_items.reset();
109	        m_empty.reset();
110	    }
111	
112	private:
113	    struct CacheItem
114	    {
115	        ~CacheItem()
116	        {
117	            // Iterate through all subsequent elements to avoid deep recursion
118	            while (next)
119	            {
120	                // detach the chain from the `next`
121	                auto tmp = std::move(next->next);
122	                // this will delete the next
123	                next = std::move(tmp);
124	            }
125	        }
126	
127	        std::unique_ptr<CacheItem> next;
128	        std::optional<T>           payload;
129	    };
130	
131	    std::unique_ptr<CacheItem> m_items;
132	    std::unique_ptr<CacheItem> m_empty;
133	    LockType                   m_lock;
134	};
135	
136	} // namespace nvcv::util
137	
138	#endif // NVCV_UTIL_SIMPLE_CACHE_HPP
