97	{
98	    constexpr int                          kMaxItemsOnStack = 256;
99	    std::array<item_t *, kMaxItemsOnStack> tmp;
100	    item_t                                *sectionStart = m_tail;
101	    // Process the items in blocks of up to kMaxItemsOnStack. On each block, a binary search is performed.
102	    while (sectionStart)
103	    {
104	        if (sectionStart->isReady())
105	            return sectionStart; // everything elese is newer, hence also ready
106	
107	        item_t *it = sectionStart->prev; // no point in re-checking the section start
108	        int     hi = 0;
109	        for (; it && hi < kMaxItemsOnStack; hi++, it = it->prev) tmp[hi] = it;
110	
111	        if (hi == 0)
112	            return nullptr;
113	
114	        // There are no ready elements in this range - move on
115	        if (!tmp[hi - 1]->isReady())
116	        {
117	            sectionStart = it;
118	            continue;
119	        }
120	
121	        int lo = 0;
122	        int m  = (lo + hi) >> 1;
123	        // After this loop, `m` is going to contain the index of the newest ready element
124	        while (lo < hi) // exclusive upper bound
125	        {
126	            // halfway element is ready - maybe there are newer ones that are ready, too?
127	            if (tmp[m]->isReady())
128	            {
129	                hi = m; // exclusive upper bound
130	                m  = (lo + hi) >> 1;
131	            }
132	            else // halfway element isn't ready - move to `m+1` as a potential lower bound
133	            {
134	                lo = m + 1;
135	                m  = (lo + hi) >> 1;
